using System;using System.Linq;using System.Text;using PersistentFlight;
class RoverRouteTests {
 static int checks;static double radius=200000;static RoverPoint home=new RoverPoint(0,0);
 static void Check(bool ok,string label){checks++;if(!ok)throw new Exception(label);}static void Near(double a,double b,double tolerance,string label){Check(Math.Abs(a-b)<tolerance,label+": "+a+" / "+b);}static void Reject(Action action,string label){bool rejected=false;try{action();}catch{rejected=true;}Check(rejected,label);}
 static RoverPoint At(double metres){return home.Offset(90,metres,radius);}static RoverRoute Route(bool auto=true,double stuck=15){return new RoverRoute(new RoverRouteRequest(Guid.NewGuid(),"Mun",home,new[]{At(100),At(200)},3,5,15,.25,stuck,auto));}
 static RoverObservation Obs(RoverPoint p,double ut,double power=900,double speed=1){return new RoverObservation{Body="Mun",Position=p,UT=ut,Radius=radius,Power=power,Capacity=1000,Speed=speed,Slope=0};}
 static string Change(string data,int column,string value){var rows=Encoding.UTF8.GetString(Convert.FromBase64String(data)).Split('\n');var fields=rows[0].Split('|');fields[column]=value;rows[0]=String.Join("|",fields);return Convert.ToBase64String(Encoding.UTF8.GetBytes(String.Join("\n",rows)));}
 static void Main(){try{Geometry();Navigation();Holds();Persistence();RandomGeometry();Console.WriteLine("PASS "+checks+" rover route checks");}catch(Exception e){Console.Error.WriteLine("FAIL "+e);Environment.Exit(1);}}
 static void Geometry(){Near(home.Distance(At(100),radius),100,1e-6,"100 m geodesic");Near(home.Bearing(At(100)),90,1e-6,"East bearing");Near(new RoverPoint(0,179.999).Distance(new RoverPoint(0,-179.999),radius),radius*Math.PI*.002/180,1e-6,"Dateline shortest distance");Near(home.Distance(new RoverPoint(0,180),radius),Math.PI*radius,1e-6,"Antipodes");Reject(()=>new RoverPoint(Double.NaN,0),"NaN point");Reject(()=>new RoverPoint(0,181),"Longitude bounds");Reject(()=>new RoverRouteRequest(Guid.Empty,"Mun",home,new[]{At(100)},3,5,15,.25,15,true),"Missing identity");Reject(()=>new RoverRouteRequest(Guid.NewGuid(),"Mun",home,new RoverPoint[0],3,5,15,.25,15,true),"No stops");var q=Route().Request;var copy=q.Waypoints;copy[0]=home;Check(q.Waypoints[0]!=home,"Detached waypoint array");}
 static void Navigation(){
  var r=Route();Check(r.Tick(Obs(home,1)).Speed==3,"Cruise command");Check(r.Tick(Obs(At(95),2,900,1)).Events.Length==0,"Must stop to acknowledge waypoint");var first=r.Tick(Obs(At(100),3,899,0));Check(first.Speed==0&&first.Events.SequenceEqual(new[]{"WAYPOINT_REACHED"})&&r.Index==1,"First stop advances with brake");
  var finish=r.Tick(Obs(At(200),4,890,0));Check(r.Mode==RoverMode.Complete&&finish.Speed==0&&finish.Events.SequenceEqual(new[]{"WAYPOINT_REACHED","ARRIVED"}),"Final stop completes once");Check(r.Tick(Obs(At(200),5)).Events.Length==0,"Completion not replayed");Reject(()=>r.Resume(),"Cannot resume completed route");r.ReturnHome();Check(r.Mode==RoverMode.Returning&&r.Target.Distance(At(200),radius)<1,"Return from completed route");
  int count=0;while(r.Active&&count++<20){var target=r.Target;r.Tick(Obs(target,5+count,800,0));}Check(r.Mode==RoverMode.Home&&count<20,"Retrace all stops to home");Reject(()=>r.ReturnHome(),"Cannot reopen home route");
  r=Route();r.Tick(Obs(home,1));r.Tick(Obs(At(30),2,899));r.Tick(Obs(At(60),3,898));var low=r.Tick(Obs(At(70),4,240));Check(low.Speed==0&&r.Mode==RoverMode.Returning&&low.Events.Contains("ROVER_RETURNING"),"Reserve initiates return");Check(r.Trace.Length==3&&r.Target.Distance(At(60),radius)<1,"Return uses actual intermediate breadcrumbs");Near(low.ReturnDistance,70,1e-5,"Return length");
  r=Route(false);Check(r.Tick(Obs(At(20),1,240)).Speed==0&&r.Hold==RoverHold.Power,"Reserve holds when return disabled");
  r=Route();r.Tick(Obs(home,1,1000));r.Tick(Obs(At(50),2,650));Check(r.Tick(Obs(At(70),3,510)).Events.Contains("ROVER_RETURNING"),"Measured energy forecast returns above percentage reserve");
  r=Route();var downhill=Obs(home,1);downhill.Slope=12;Check(r.Tick(downhill).Speed<3,"Slope reduces speed");Check(Route().Tick(Obs(At(94),1)).Speed<1,"Slows before stop");
  r=Route();r.Cancel();Check(!r.Active&&r.Tick(Obs(home,1)).Speed==0,"Cancel stops driving");Reject(()=>r.Resume(),"Cancel cannot resume");
 }
 static void Holds(){
  foreach(int hazard in Enumerable.Range(0,5)){var r=Route();var o=Obs(home,1);if(hazard==0)o.Slope=16;if(hazard==1)o.TerrainValid=false;if(hazard==2)o.Water=true;if(hazard==3)o.Slope=Double.NaN;if(hazard==4)o.Slope=-1;Check(r.Tick(o).Speed==0&&r.Hold==RoverHold.Terrain,"Terrain hold "+hazard);Check(r.Tick(Obs(home,2)).Speed==0,"Terrain hold latches "+hazard);r.Resume();Check(r.Tick(Obs(home,3)).Speed>0,"Explicit terrain resume "+hazard);}
  var edge=Route();Check(edge.Tick(Obs(At(94.9),1)).Speed>=.8,"Finite crawl crosses arrival boundary");Check(edge.Tick(Obs(At(94.9),16)).Events.Contains("ROVER_STUCK"),"Stall beside arrival boundary also times out");
  var stuck=Route();stuck.Tick(Obs(home,1));Check(stuck.Tick(Obs(home,16)).Events.Contains("ROVER_STUCK"),"No progress times out");stuck.Resume();Check(stuck.Tick(Obs(home,100)).Speed>0,"Resume resets stuck timer");
  var moving=Route();for(int i=0;i<30;i++)Check(moving.Tick(Obs(At(i),i+1)).Speed>0,"Steady progress avoids stuck "+i);
  var pause=Route();pause.Tick(Obs(home,1));var o2=Obs(home,1000);o2.Paused=true;Check(pause.Tick(o2).Speed==0&&pause.Hold==RoverHold.None,"Player pause exempt from stuck");Check(pause.Tick(Obs(home,1001)).Speed>0,"Unpause starts new watch");o2=Obs(home,2000);o2.Supported=false;Check(pause.Tick(o2).Speed==0&&pause.Hold==RoverHold.None,"Unsupported wheels wait");
  var body=Route();o2=Obs(home,1);o2.Body="Minmus";Check(body.Tick(o2).Speed==0&&body.Hold==RoverHold.Body,"Body guard");var clock=Route();clock.Tick(Obs(home,100));Check(clock.Tick(Obs(home,90)).Speed==0&&clock.Hold==RoverHold.Clock,"Time reversal hold");var power=Route();Check(power.Tick(Obs(home,1,5)).Speed==0&&power.Hold==RoverHold.Power,"Critical power stops return");Reject(()=>Route().Tick(Obs(home,Double.NaN)),"Invalid observations rejected");
 }
 static void Persistence(){
  var r=Route();r.Tick(Obs(home,1));r.Tick(Obs(At(30),2,899));r.Tick(Obs(At(60),3,895));r.ReturnHome();var s=r.Save();var restored=RoverRoute.Load(s);Check(restored.Save()==s,"Exact checkpoint round trip");Check(restored.Request.Id==r.Request.Id&&restored.Trace.Length==r.Trace.Length&&restored.ReturnIndex==r.ReturnIndex,"Identity and return cursor preserved");Near(restored.EnergyPerMetre,r.EnergyPerMetre,1e-9,"Energy estimate preserved");
  var paused=Route();paused.Tick(Obs(home,1));var cold=RoverRoute.Load(paused.Save());cold.ResetObservation();Check(cold.Tick(Obs(home,1000)).Speed>0&&cold.Hold==RoverHold.None,"Cold load rebases watchdog");
  foreach(var bad in new[]{"", "bad",Change(s,0,"PFROUTE9"),Change(s,10,"0"),Change(s,24,"1025"),Change(s,11,"99"),Change(s,12,"-1"),Change(s,13,"999"),Change(s,14,"99"),Change(s,15,"NaN"),Change(s,16,"-1"),Change(s,23,"999999")})Reject(()=>RoverRoute.Load(bad),"Malformed checkpoint");
  var cap=Route();string many=Change(cap.Save(),24,"1024");string raw=Encoding.UTF8.GetString(Convert.FromBase64String(many));raw+=String.Concat(Enumerable.Range(1,1023).Select(i=>"\n0,"+(i*.0001).ToString(System.Globalization.CultureInfo.InvariantCulture)));var full=RoverRoute.Load(Convert.ToBase64String(Encoding.UTF8.GetBytes(raw)));var decision=full.Tick(Obs(At(3000),1));Check(full.Hold==RoverHold.TraceFull&&decision.Speed==0&&full.Trace.Length==1024,"Full trace safely holds without truncating home path");
 }
 static void RandomGeometry(){var random=new Random(125);for(int i=0;i<10000;i++){var point=new RoverPoint(random.NextDouble()*178-89,random.NextDouble()*360-180);double bearing=random.NextDouble()*360,metres=random.NextDouble()*1000;var target=point.Offset(bearing,metres,radius);Near(point.Distance(target,radius),metres,.00001,"Random geodesic distance");double delta=(point.Bearing(target)-bearing+540)%360-180;Near(delta,0,.00001,"Random geodesic bearing");}}
}
